dim N;
array out[N];
out[i] = 0;

// Sum of x[0..4] as a balanced tree.
dim N;
dim K;
array x[K];
array out[N];

out[i] = (x[0] + x[1]) + (x[2] + x[3]);

// The balanced tree with its last leaf doubled.
dim N;
dim K;
array x[K];
array out[N];

out[i] = (x[0] + x[1]) + (x[2] + (x[3] + x[3]));

// x * 0.5.
dim N;
array x[N];
array out[N];

out[i] = x[i] * 0.5;

// x0 * x1 + x3.
dim N;
dim K;
array x[K];
array out[N];

out[i] = x[0] * x[1] + x[3];

// x0 * x1 + x2.
dim N;
dim K;
array x[K];
array out[N];

out[i] = x[0] * x[1] + x[2];

// Sum of x[0..4] with the last term dropped.
dim N;
dim K;
array x[K];
array out[N];

out[i] = x[0] + x[1] + x[2];

// |a - b| + c = c + |-b + a|. (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = abs(a[i] - b[i]) + c[i];

// |a - b| + c = c + |-b + a|. (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = c[i] + abs(-b[i] + a[i]);

// a + b - b = a. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] + b[i] - b[i];

// a + b - b = a. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i];

// a + b = b + a. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] + b[i];

// a + b = b + a. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = b[i] + a[i];

// softmax(QK^T)V: safe softmax with one division vs naive weights each divided. (left side)
dim N;
dim D;
array Q[N, D];
array K[N, D];
array V[N, D];
array O[N, D];

O[i, e] = sum(j in 0..N, exp(sum(d in 0..D, Q[i, d] * K[j, d])
                            - max(m in 0..N, sum(d in 0..D, Q[i, d] * K[m, d]))) * V[j, e])
        / sum(j in 0..N, exp(sum(d in 0..D, Q[i, d] * K[j, d])
                            - max(m in 0..N, sum(d in 0..D, Q[i, d] * K[m, d]))));

// softmax(QK^T)V: safe softmax with one division vs naive weights each divided. (right side)
dim N;
dim D;
array Q[N, D];
array K[N, D];
array V[N, D];
array O[N, D];

O[i, e] = sum(j in 0..N, exp(sum(d in 0..D, Q[i, d] * K[j, d]))
                        / sum(l in 0..N, exp(sum(d in 0..D, Q[i, d] * K[l, d]))) * V[j, e]);

// (a - b)^3 expanded. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = pow(a[i] - b[i], 3);

// (a - b)^3 expanded. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] * a[i] * a[i] - 3 * a[i] * a[i] * b[i]
       + 3 * a[i] * b[i] * b[i] - b[i] * b[i] * b[i];

// (a + b)^2 = a^2 + 2ab + b^2. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = pow(a[i] + b[i], 2);

// (a + b)^2 = a^2 + 2ab + b^2. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] * a[i] + 2 * a[i] * b[i] + b[i] * b[i];

// sum (x_k - mean) = 0. (left side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, x[k] - sum(m in 0..N, x[m]) / N);

// sum (x_k - mean) = 0. (right side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = 0;

// (ab)/b = a (canon's field model). (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = (a[i] * b[i]) / b[i];

// (ab)/b = a (canon's field model). (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i];

// sum 2x_k = 2 sum x_k. (left side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, 2 * x[k]);

// sum 2x_k = 2 sum x_k. (right side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = 2 * sum(k in 0..N, x[k]);

// a(0.5 + 0.25) = 0.75a. (left side)
dim N;
array a[N];
array out[N];

out[i] = a[i] * (0.5 + 0.25);

// a(0.5 + 0.25) = 0.75a. (right side)
dim N;
array a[N];
array out[N];

out[i] = 0.75 * a[i];

// A 3-tap convolution as a reduction vs unrolled out of order. (left side)
dim N;
dim K;
dim M;
array x[M];
array w[K];
array out[N];

out[i] = sum(k in 0..K, x[i + k] * w[k]);

// A 3-tap convolution as a reduction vs unrolled out of order. (right side)
dim N;
dim K;
dim M;
array x[M];
array w[K];
array out[N];

out[i] = w[2] * x[i + 2] + w[0] * x[i] + x[i + 1] * w[1];

// (a - b)(a + b) = a^2 - b^2. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = (a[i] - b[i]) * (a[i] + b[i]);

// (a - b)(a + b) = a^2 - b^2. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] * a[i] - b[i] * b[i];

// s/4 = s * 0.25. (left side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, x[k]) / 4;

// s/4 = s * 0.25. (right side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, x[k]) * 0.25;

// sum a_k b_k = sum b_k a_k. (left side)
dim N;
dim O;
array a[N];
array b[N];
array out[O];

out[o] = sum(k in 0..N, a[k] * b[k]);

// sum a_k b_k = sum b_k a_k. (right side)
dim N;
dim O;
array a[N];
array b[N];
array out[O];

out[o] = sum(k in 0..N, b[k] * a[k]);

// 1/(1/a) = a. (left side)
dim N;
array a[N];
array out[N];

out[i] = 1 / (1 / a[i]);

// 1/(1/a) = a. (right side)
dim N;
array a[N];
array out[N];

out[i] = a[i];

// e^(2a) = e^a e^a. (left side)
dim N;
array a[N];
array out[N];

out[i] = exp(2 * a[i]);

// e^(2a) = e^a e^a. (right side)
dim N;
array a[N];
array out[N];

out[i] = exp(a[i]) * exp(a[i]);

// e^(a(b + c)) = e^(ab) e^(ca). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = exp(a[i] * (b[i] + c[i]));

// e^(a(b + c)) = e^(ab) e^(ca). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = exp(a[i] * b[i]) * exp(c[i] * a[i]);

// e^(a - a) b = b. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = exp(a[i] - a[i]) * b[i];

// e^(a - a) b = b. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = b[i];

// a/b + c/d = (ad + bc)/(bd). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = a[i] / b[i] + c[i] / d[i];

// a/b + c/d = (ad + bc)/(bd). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = (a[i] * d[i] + b[i] * c[i]) / (b[i] * d[i]);

// a/b + c/b = (a + c)/b. (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = a[i] / b[i] + c[i] / b[i];

// a/b + c/b = (a + c)/b. (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = (a[i] + c[i]) / b[i];

// 2(AB) + 3C with the 2 moved into the sum. (left side)
dim N;
array A[N, N];
array B[N, N];
array C[N, N];
array D[N, N];

D[i, j] = 2 * sum(k in 0..N, A[i, k] * B[k, j]) + 3 * C[i, j];

// 2(AB) + 3C with the 2 moved into the sum. (right side)
dim N;
array A[N, N];
array B[N, N];
array C[N, N];
array D[N, N];

D[i, j] = sum(k in 0..N, 2 * A[i, k] * B[k, j]) + C[i, j] * 3;

// ad^2 + bd + c in Horner form. (left side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = a[i] * d[i] * d[i] + b[i] * d[i] + c[i];

// ad^2 + bd + c in Horner form. (right side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = c[i] + d[i] * (b[i] + d[i] * a[i]);

// 2a + 3a = 5a. (left side)
dim N;
array a[N];
array out[N];

out[i] = 2 * a[i] + 3 * a[i];

// 2a + 3a = 5a. (right side)
dim N;
array a[N];
array out[N];

out[i] = 5 * a[i];

// log(a + b) c = c log(b + a). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = log(a[i] + b[i]) * c[i];

// log(a + b) c = c log(b + a). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = c[i] * log(b[i] + a[i]);

// (AB)C = A(BC). (left side)
dim N;
array A[N, N];
array B[N, N];
array C[N, N];
array D[N, N];

D[i, j] = sum(l in 0..N, sum(k in 0..N, A[i, k] * B[k, l]) * C[l, j]);

// (AB)C = A(BC). (right side)
dim N;
array A[N, N];
array B[N, N];
array C[N, N];
array D[N, N];

D[i, j] = sum(k in 0..N, A[i, k] * sum(l in 0..N, B[k, l] * C[l, j]));

// max(a, max(b, c)) = max(max(c, a), b). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = max(a[i], max(b[i], c[i]));

// max(a, max(b, c)) = max(max(c, a), b). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = max(max(c[i], a[i]), b[i]);

// max(a, a) = a. (left side)
dim N;
array a[N];
array out[N];

out[i] = max(a[i], a[i]);

// max(a, a) = a. (right side)
dim N;
array a[N];
array out[N];

out[i] = a[i];

// max(a + b, c) = max(c, b + a). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = max(a[i] + b[i], c[i]);

// max(a + b, c) = max(c, b + a). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = max(c[i], b[i] + a[i]);

// min(a, min(b, c)) = min(min(c, a), b). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = min(a[i], min(b[i], c[i]));

// min(a, min(b, c)) = min(min(c, a), b). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = min(min(c[i], a[i]), b[i]);

// (ab)c = a(bc). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = (a[i] * b[i]) * c[i];

// (ab)c = a(bc). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = a[i] * (b[i] * c[i]);

// ab = ba. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = a[i] * b[i];

// ab = ba. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = b[i] * a[i];

// a(b + c) = ab + ca. (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = a[i] * (b[i] + c[i]);

// a(b + c) = ab + ca. (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = a[i] * b[i] + c[i] * a[i];

// -(a - b) = b - a. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = -(a[i] - b[i]);

// -(a - b) = b - a. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = b[i] - a[i];

// (a/b)/(c/d) = (ad)/(bc). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = (a[i] / b[i]) / (c[i] / d[i]);

// (a/b)/(c/d) = (ad)/(bc). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array d[N];
array out[N];

out[i] = (a[i] * d[i]) / (b[i] * c[i]);

// sum_i sum_j A_ij = sum_j sum_i A_ij. (left side)
dim M;
dim N;
dim O;
array A[M, N];
array out[O];

out[o] = sum(i in 0..M, sum(j in 0..N, A[i, j]));

// sum_i sum_j A_ij = sum_j sum_i A_ij. (right side)
dim M;
dim N;
dim O;
array A[M, N];
array out[O];

out[o] = sum(j in 0..N, sum(i in 0..M, A[i, j]));

// FlashAttention's online softmax: two blocks of two, the first rescaled by e^(m1 - m). (left side)
dim N;
array x[N];
array y[N];

y[i] = exp(x[i]) / sum(k in 0..N, exp(x[k]));

// FlashAttention's online softmax: two blocks of two, the first rescaled by e^(m1 - m). (right side)
dim N;
array x[N];
array y[N];

y[i] = exp(x[i] - max(max(x[0], x[1]), max(x[2], x[3])))
     / (exp(max(x[0], x[1]) - max(max(x[0], x[1]), max(x[2], x[3])))
          * (exp(x[0] - max(x[0], x[1])) + exp(x[1] - max(x[0], x[1])))
        + exp(x[2] - max(max(x[0], x[1]), max(x[2], x[3])))
        + exp(x[3] - max(max(x[0], x[1]), max(x[2], x[3]))));

// x_i y_j = y_j x_i. (left side)
dim N;
array x[N];
array y[N];
array P[N, N];

P[i, j] = x[i] * y[j];

// x_i y_j = y_j x_i. (right side)
dim N;
array x[N];
array y[N];
array P[N, N];

P[i, j] = y[j] * x[i];

// sqrt(a)(b + c) = c sqrt(a) + sqrt(a) b. (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = sqrt(a[i]) * (b[i] + c[i]);

// sqrt(a)(b + c) = c sqrt(a) + sqrt(a) b. (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = c[i] * sqrt(a[i]) + sqrt(a[i]) * b[i];

// e^a e^b e^c = e^(a + b + c). (left side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = exp(a[i]) * exp(b[i]) * exp(c[i]);

// e^a e^b e^c = e^(a + b + c). (right side)
dim N;
array a[N];
array b[N];
array c[N];
array out[N];

out[i] = exp(a[i] + b[i] + c[i]);

// e^a / e^b = e^(a - b). (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = exp(a[i]) / exp(b[i]);

// e^a / e^b = e^(a - b). (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = exp(a[i] - b[i]);

// max(a, 0) = max(0, a). (left side)
dim N;
array a[N];
array out[N];

out[i] = max(a[i], 0.0);

// max(a, 0) = max(0, a). (right side)
dim N;
array a[N];
array out[N];

out[i] = max(0.0, a[i]);

// a - a = 0. (left side)
dim N;
array a[N];
array out[N];

out[i] = a[i] - a[i];

// a - a = 0. (right side)
dim N;
array a[N];
array out[N];

out[i] = 0;

// 1/(1 + e^-a) = e^a/(e^a + 1). (left side)
dim N;
array a[N];
array out[N];

out[i] = 1 / (1 + exp(-a[i]));

// 1/(1 + e^-a) = e^a/(e^a + 1). (right side)
dim N;
array a[N];
array out[N];

out[i] = exp(a[i]) / (exp(a[i]) + 1);

// sign(2a) b = b sign(2a), operands reordered. (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = sign(a[i] * 2) * b[i];

// sign(2a) b = b sign(2a), operands reordered. (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = b[i] * sign(2 * a[i]);

// Shifting every logit by the same c leaves softmax unchanged. (left side)
dim N;
dim C;
array x[N];
array c[C];
array y[N];

y[i] = exp(x[i] - c[0]) / sum(k in 0..N, exp(x[k] - c[0]));

// Shifting every logit by the same c leaves softmax unchanged. (right side)
dim N;
dim C;
array x[N];
array c[C];
array y[N];

y[i] = exp(x[i]) / sum(k in 0..N, exp(x[k]));

// softmax(x/2), naive vs max-subtracted. (left side)
dim N;
array x[N];
array y[N];

y[i] = exp(x[i] / 2) / sum(k in 0..N, exp(x[k] / 2));

// softmax(x/2), naive vs max-subtracted. (right side)
dim N;
array x[N];
array y[N];

y[i] = exp(0.5 * x[i] - 0.5 * max(k in 0..N, x[k]))
     / sum(k in 0..N, exp(0.5 * x[k] - 0.5 * max(m in 0..N, x[m])));

// sqrt(ab) = sqrt(ba). (left side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = sqrt(a[i] * b[i]);

// sqrt(ab) = sqrt(ba). (right side)
dim N;
array a[N];
array b[N];
array out[N];

out[i] = sqrt(b[i] * a[i]);

// sum x_k = sum x_(N-1-k). (left side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, x[k]);

// sum x_k = sum x_(N-1-k). (right side)
dim N;
dim O;
array x[N];
array out[O];

out[o] = sum(k in 0..N, x[N - 1 - k]);

// sum (a_k + b_k) = sum a_k + sum b_k. (left side)
dim N;
dim O;
array a[N];
array b[N];
array out[O];

out[o] = sum(k in 0..N, a[k] + b[k]);

// sum (a_k + b_k) = sum a_k + sum b_k. (right side)
dim N;
dim O;
array a[N];
array b[N];
array out[O];

out[o] = sum(k in 0..N, a[k]) + sum(k in 0..N, b[k]);

// tanh(a) = 2 sigmoid(2a) - 1. (left side)
dim N;
array a[N];
array out[N];

out[i] = tanh(a[i]);

// tanh(a) = 2 sigmoid(2a) - 1. (right side)
dim N;
array a[N];
array out[N];

out[i] = 2 / (1 + exp(-2 * a[i])) - 1;

// tanh(a) = (1 - e^-2a)/(1 + e^-2a). (left side)
dim N;
array a[N];
array out[N];

out[i] = tanh(a[i]);

